//! Hardcoded Paillier safe-prime pairs for the **trusted dealer** used by
//! [`crate::UsdtInit::trusted_dealer_gen`].
//!
//! # Why this exists
//!
//! `trusted_dealer_gen` mocks distributed key generation in a single place for
//! **tests and devimint config-gen only**. The cggmp21 trusted dealer normally
//! generates a fresh Paillier safe prime pair per guardian at runtime; safe
//! prime search is extremely slow (minutes), which dominates the wall-clock of
//! every unit test that needs guardian configs.
//!
//! Since the trusted dealer already reconstructs the full signing secret in one
//! place — it provides **no** security over a real DKG and is categorically
//! unfit for production — the Paillier primes it uses carry no additional
//! secrecy requirement in that setting. We therefore embed a fixed pool of
//! pregenerated pairs and inject them via
//! [`cggmp21::trusted_dealer::TrustedDealerBuilder::set_pregenerated_primes`],
//! making config generation instant.
//!
//! # Security scope (read before touching)
//!
//! These primes are **public** and must never be used anywhere but the trusted
//! dealer. Real deployments run [`crate::UsdtInit::distributed_gen`] (see
//! `dkg.rs`), which keeps generating fresh primes per guardian via
//! [`cggmp21::PregeneratedPrimes::generate`] and MUST NOT be changed to use
//! this pool.
//!
//! The pool was generated once with the ignored `regenerate_pool` test below
//! (`SecurityLevel128`, the crate default). To regenerate, run it and paste the
//! printed decimal literals back into [`PRIMES_DECIMAL`].

use cggmp21::rug::Integer;

/// Number of embedded `(p, q)` safe-prime pairs. Covers every federation size
/// exercised by the unit tests (all `n = 4`) with a small margin. For larger
/// `n`, [`pregenerated_primes`] returns `None` and the caller falls back to
/// live generation.
pub(crate) const POOL_SIZE: usize = 4;

/// Fixed pool of `(p, q)` Paillier safe primes in base-10, one pair per
/// guardian. See the module docs for provenance and the security scope.
const PRIMES_DECIMAL: [(&str, &str); POOL_SIZE] = [
    (
        "",
        "",
    ),
    (
        "",
        "",
    ),
    (
        "",
        "",
    ),
    (
        "",
        "",
    ),
];

/// Returns a `Vec` of exactly `n` pregenerated `(p, q)` prime pairs suitable
/// for [`cggmp21::trusted_dealer::TrustedDealerBuilder::set_pregenerated_primes`],
/// or `None` when `n` exceeds [`POOL_SIZE`] (caller should generate fresh).
pub(crate) fn pregenerated_primes(n: usize) -> Option<Vec<(Integer, Integer)>> {
    if n > POOL_SIZE {
        return None;
    }
    Some(
        PRIMES_DECIMAL[..n]
            .iter()
            .map(|(p, q)| (parse(p), parse(q)))
            .collect(),
    )
}

fn parse(decimal: &str) -> Integer {
    Integer::from_str_radix(decimal, 10)
        .expect("embedded trusted-dealer prime is a valid base-10 integer")
}

#[cfg(test)]
mod tests {
    use super::*;

    /// Regenerates the embedded prime pool. Ignored by default because safe
    /// prime search takes minutes. Run with:
    /// `cargo test -p fedimint-usdt-server
    /// trusted_dealer_primes::tests::regenerate_pool -- --ignored --nocapture`
    /// then paste the printed literals into `PRIMES_DECIMAL`.
    #[test]
    #[ignore = "safe-prime generation takes minutes; run manually to regenerate the pool"]
    fn regenerate_pool() {
        use rand::rngs::OsRng;
        println!("[");
        for _ in 0..POOL_SIZE {
            let (p, q) =
                cggmp21::PregeneratedPrimes::<cggmp21::security_level::SecurityLevel128>::generate(
                    &mut OsRng,
                )
                .split();
            println!("    (\"{p}\", \"{q}\"),");
        }
        println!("]");
    }

    #[test]
    fn pool_parses_and_slices() {
        assert_eq!(pregenerated_primes(0).unwrap().len(), 0);
        let full = pregenerated_primes(POOL_SIZE).unwrap();
        assert_eq!(full.len(), POOL_SIZE);
        // Every embedded value parses and is a plausible RSA-ish prime (odd,
        // large). This is a cheap sanity check, not a primality test.
        for (p, q) in &full {
            assert!(p.is_odd() && q.is_odd());
            assert!(p.significant_bits() > 512 && q.significant_bits() > 512);
        }
        assert!(pregenerated_primes(POOL_SIZE + 1).is_none());
    }
}
